node -e '
import("./eligibility.mjs").then(m => {
  const cases = [18, 17, -1, -5, 0, 19];
  for (const c of cases) {
    let r;
    try { r = JSON.stringify(m.eligible(c)); } catch (e) { r = "THREW: " + e.constructor.name + ": " + e.message; }
    console.log("eligible(" + JSON.stringify(c) + ") =>", r);
  }
});'

node -e '
import("./eligibility.mjs").then(m => {
  const cases = [undefined, null, NaN, "18", "17", "abc", true, {}, [], [18], Infinity, -Infinity, 17.5];
  for (const c of cases) {
    let r;
    try { r = String(m.eligible(c)); } catch (e) { r = "THREW: " + e.constructor.name; }
    console.log(String(typeof c).padEnd(9), JSON.stringify(c) ?? String(c), "=>", r);
  }
});'

node -e '
import("./eligibility.mjs").then(m => {
  const show = (label, v) => console.log(label.padEnd(14), "=>", String(m.eligible(v)));
  show("NaN", NaN);
  show("Infinity", Infinity);
  show("-Infinity", -Infinity);
  show("-0", -0);
  show("17.999", 17.999);
  show("18.5", 18.5);
  show("-100", -100);
  show("\"-100\"", "-100");
  show("\" 18 \"", " 18 ");
  show("[18]", [18]);
  show("new Date()", new Date());
});'
